import{_ as n,C as a,o as l,c,E as o,j as t,a as d,a7 as h}from"./chunks/framework.BWEz4cKd.js";const g=JSON.parse('{"title":"100 个 CSS 优化技巧分享！","description":"","frontmatter":{"author":"Sunday","reprinted":true,"title":"100 个 CSS 优化技巧分享！","date":"2024/09/20","words":4023,"duration":15,"categories":["CSS"],"tags":["CSS"]},"headers":[],"relativePath":"other/css/100CssSkills.md","filePath":"other/css/100CssSkills.md","lastUpdated":1726993907000}'),p={name:"other/css/100CssSkills.md"};function s(u,e,b,f,x,m){const r=a("BackTop"),i=a("ArticleMetadata");return l(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1726761600000"},[o(r),e[0]||(e[0]=t("h1",{id:"_100-个-css-优化技巧分享",tabindex:"-1"},[d("100 个 CSS 优化技巧分享！ "),t("a",{class:"header-anchor",href:"#_100-个-css-优化技巧分享","aria-label":'Permalink to "100 个 CSS 优化技巧分享！"'},"​")],-1)),o(i,{article:{}}),e[1]||(e[1]=h('<p>当各种框架以及复杂的 JS 知识开始充斥着我们的工作环境时。谁还能够记得，以 CSS 来构建更加良好的用户体验，也是前端的一个重要组成部分。</p><p>所以说，今天咱们就来看看 <strong><code>css 的优化方案-终极合集</code></strong>。一共一百条，有点多，适合收藏（点个赞和分享自然更好了 😂😂）</p><h2 id="_01-启动平滑滚动" tabindex="-1">01. 启动平滑滚动 <a class="header-anchor" href="#_01-启动平滑滚动" aria-label="Permalink to &quot;01\\. 启动平滑滚动&quot;">​</a></h2><p>添加 scroll-behavior：smooth 到元素中<code>&lt;html&gt;</code>，使整个页面能够平滑滚动。</p><p><code>html{       scroll-behavior: smooth;     } </code></p><h2 id="_02-链接的属性选择器" tabindex="-1">02. 链接的属性选择器 <a class="header-anchor" href="#_02-链接的属性选择器" aria-label="Permalink to &quot;02\\. 链接的属性选择器&quot;">​</a></h2><p>此选择器以 href 属性以“https”开头的链接为目标。</p><p><code>a[href^=&quot;https&quot;] {     color: blue; } </code></p><h2 id="_03-用于合并节点" tabindex="-1">03. ~用于合并节点 <a class="header-anchor" href="#_03-用于合并节点" aria-label="Permalink to &quot;03\\. ~用于合并节点&quot;">​</a></h2><p>选择作为<code>&lt;h2&gt;</code>同级元素的所有<code>&lt;p&gt;</code>元素。</p><p><code>h2 ~ p {     color: blue; } </code></p><h2 id="_04-not-伪类" tabindex="-1">04. :not()伪类 <a class="header-anchor" href="#_04-not-伪类" aria-label="Permalink to &quot;04\\. :not()伪类&quot;">​</a></h2><p>此选择器将样式应用于不具有类“Special”的 li。</p><p><code>li:not(.special) {     font-style: italic; } </code></p><h2 id="_05-响应式排版的视窗单位-vw" tabindex="-1">05. 响应式排版的视窗单位 vw <a class="header-anchor" href="#_05-响应式排版的视窗单位-vw" aria-label="Permalink to &quot;05\\. 响应式排版的视窗单位 vw&quot;">​</a></h2><p>使用视区单位(vw, vh, vmin, vmax)可以使字体大小与视区大小相对应。</p><p><code>h1 {     font-size: 5vw; } </code></p><h2 id="_06-empty-对于空元素" tabindex="-1">06. :empty 对于空元素 <a class="header-anchor" href="#_06-empty-对于空元素" aria-label="Permalink to &quot;06\\. :empty 对于空元素&quot;">​</a></h2><p>此选择器以空的<code>&lt;p&gt;</code>元素为目标并隐藏它们。</p><p><code>p:empty {     display: none; } </code></p><h2 id="_07-自定义特性-变量" tabindex="-1">07. 自定义特性(变量) <a class="header-anchor" href="#_07-自定义特性-变量" aria-label="Permalink to &quot;07\\. 自定义特性(变量)&quot;">​</a></h2><p>可以定义和使用自定义特性，以便更轻松地创建主题和进行维护。</p><p><code>:root {     --main-color: #3498db; } h1 {     color: var(--main-color); } </code></p><h2 id="_08-object-fit-图像控件的适配性" tabindex="-1">08. Object-fit 图像控件的适配性 <a class="header-anchor" href="#_08-object-fit-图像控件的适配性" aria-label="Permalink to &quot;08\\. Object-fit 图像控件的适配性&quot;">​</a></h2><p>object-fit 控制替换元素(如<code>&lt;img&gt;</code>)的内容应该如何调整大小。</p><p><code>img {     width: 100px;     height: 100px;     object-fit: cover; } </code></p><h2 id="_09-简化布局的网格" tabindex="-1">09. 简化布局的网格 <a class="header-anchor" href="#_09-简化布局的网格" aria-label="Permalink to &quot;09\\. 简化布局的网格&quot;">​</a></h2><p>Css 网格提供了一种功能强大的方式来以更直接的方式创建布局。</p><p><code>.container {     display: grid;     grid-template-columns: 1fr 2fr 1fr; } </code></p><h2 id="_10-focus-within-伪类" tabindex="-1">10. :focus-within 伪类 <a class="header-anchor" href="#_10-focus-within-伪类" aria-label="Permalink to &quot;10\\. :focus-within 伪类&quot;">​</a></h2><p>如果一个元素包含任何带有:focus 的子元素，则:focus-Win 会选择该元素。</p><p><code>form:focus-within {     box-shadow: 0 0 5px rgba(0, 0, 0, 0.2); } </code></p><h2 id="_11-使用-flexbox-垂直居中" tabindex="-1">11. 使用 Flexbox 垂直居中 <a class="header-anchor" href="#_11-使用-flexbox-垂直居中" aria-label="Permalink to &quot;11\\. 使用 Flexbox 垂直居中&quot;">​</a></h2><p>使用 FlexBox 可轻松地将内容在容器中水平和垂直居中。</p><p><code>.container {     display: flex;     align-items: center;     justify-content: center; } </code></p><h2 id="_12-自定义选定内容的突出显示颜色" tabindex="-1">12. 自定义选定内容的突出显示颜色 <a class="header-anchor" href="#_12-自定义选定内容的突出显示颜色" aria-label="Permalink to &quot;12\\. 自定义选定内容的突出显示颜色&quot;">​</a></h2><p>自定义在网页上选择文本时的突出显示颜色。</p><p><code>::selection {     background-color: #ffcc00;     color: #333; } </code></p><h2 id="_13-设置占位符文本的样式" tabindex="-1">13. 设置占位符文本的样式 <a class="header-anchor" href="#_13-设置占位符文本的样式" aria-label="Permalink to &quot;13\\. 设置占位符文本的样式&quot;">​</a></h2><p>设置输入字段内占位符文本的样式。</p><p><code>::placeholder {     color: #999;     font-style: italic; } </code></p><h2 id="_14-渐变边界" tabindex="-1">14. 渐变边界 <a class="header-anchor" href="#_14-渐变边界" aria-label="Permalink to &quot;14\\. 渐变边界&quot;">​</a></h2><p>使用 Backback-Clip 属性创建渐变边框。</p><p><code>.element {     border: 2px solid transparent;     background-clip: padding-box;     background-image: linear-gradient(to right, red, blue); } </code></p><h2 id="_15-使用-vw-实现可变字体大小" tabindex="-1">15. 使用 vw 实现可变字体大小 <a class="header-anchor" href="#_15-使用-vw-实现可变字体大小" aria-label="Permalink to &quot;15\\. 使用 vw 实现可变字体大小&quot;">​</a></h2><p>根据视口宽度调整字体大小，实现更加响应式的排版。</p><p><code>body {     font-size: calc(16px + 1vw); } </code></p><h2 id="_16-使用锥形渐变创建多彩元素" tabindex="-1">16. 使用锥形渐变创建多彩元素 <a class="header-anchor" href="#_16-使用锥形渐变创建多彩元素" aria-label="Permalink to &quot;16\\. 使用锥形渐变创建多彩元素&quot;">​</a></h2><p>利用锥形渐变创建丰富多彩且动态的背景。</p><p><code>.element {     background: conic-gradient(#ff5733, #33ff57, #5733ff); } </code></p><h2 id="_17-使用-clamp-函数实现响应式文本" tabindex="-1">17. 使用 clamp()函数实现响应式文本 <a class="header-anchor" href="#_17-使用-clamp-函数实现响应式文本" aria-label="Permalink to &quot;17\\. 使用 clamp()函数实现响应式文本&quot;">​</a></h2><p>使用 clamp()函数设置字体大小的范围，确保在不同屏幕尺寸下的可读性。</p><p><code>.text {     font-size: clamp(16px, 4vw, 24px); } </code></p><h2 id="_18-使用-font-display-swap-优化字体加载" tabindex="-1">18. 使用 font-display: swap;优化字体加载 <a class="header-anchor" href="#_18-使用-font-display-swap-优化字体加载" aria-label="Permalink to &quot;18\\. 使用 font-display: swap;优化字体加载&quot;">​</a></h2><p>使用 font-display: swap;属性提高网页字体性能，让自定义字体加载时显示备用字体。</p><p><code>@font-face {     font-family: &#39;YourFont&#39;;     src: url(&#39;your-font.woff2&#39;) format(&#39;woff2&#39;);     font-display: swap; } </code></p><h2 id="_19-自定义滚动吸附点" tabindex="-1">19. 自定义滚动吸附点 <a class="header-anchor" href="#_19-自定义滚动吸附点" aria-label="Permalink to &quot;19\\. 自定义滚动吸附点&quot;">​</a></h2><p>为了实现更顺畅的滚动体验，特别是在图库或滑块中，实现自定义滚动吸附点。</p><p><code>.scroll-container {     scroll-snap-type: y mandatory; } .scroll-item {     scroll-snap-align: start; } </code></p><h2 id="_20-使用字体变体设置进行可变字体样式" tabindex="-1">20. 使用字体变体设置进行可变字体样式 <a class="header-anchor" href="#_20-使用字体变体设置进行可变字体样式" aria-label="Permalink to &quot;20\\. 使用字体变体设置进行可变字体样式&quot;">​</a></h2><p>利用可变字体和 font-variation-settings 属性对字体的粗细、样式等进行精细调节。</p><p><code>.text {     font-family: &#39;YourVariableFont&#39;, sans-serif;     font-variation-settings: &#39;wght&#39; 500, &#39;ital&#39; 1; } </code></p><h2 id="_21-自定义下划线样式" tabindex="-1">21. 自定义下划线样式 <a class="header-anchor" href="#_21-自定义下划线样式" aria-label="Permalink to &quot;21\\. 自定义下划线样式&quot;">​</a></h2><p>使用 border-bottom 和 text-decoration 的组合来自定义链接的下划线样式。</p><p><code>a {     text-decoration: none;     border-bottom: 1px solid #3498db; } </code></p><h2 id="_22-隐藏无障碍文本" tabindex="-1">22. 隐藏无障碍文本 <a class="header-anchor" href="#_22-隐藏无障碍文本" aria-label="Permalink to &quot;22\\. 隐藏无障碍文本&quot;">​</a></h2><p>使用 class sr-only 来在视觉上隐藏元素，但保持其对屏幕阅读器的可访问性。</p><p><code>.sr-only {     position: absolute;     width: 1px;     height: 1px;     margin: -1px;     padding: 0;     overflow: hidden;     clip: rect(0, 0, 0, 0);     border: 0; } </code></p><h2 id="_23-保持元素纵横比" tabindex="-1">23. 保持元素纵横比 <a class="header-anchor" href="#_23-保持元素纵横比" aria-label="Permalink to &quot;23\\. 保持元素纵横比&quot;">​</a></h2><p>通过使用 padding 来保持元素（如图片或视频）的纵横比。</p><p><code>.aspect-ratio-box {     position: relative;     width: 100%;     padding-bottom: 75%; /* 根据需要调整 */ } .aspect-ratio-box &gt; iframe {     position: absolute;     width: 100%;     height: 100%; } </code></p><h2 id="_24-选择偶数和奇数元素" tabindex="-1">24. 选择偶数和奇数元素 <a class="header-anchor" href="#_24-选择偶数和奇数元素" aria-label="Permalink to &quot;24\\. 选择偶数和奇数元素&quot;">​</a></h2><p>使用:nth-child 伪类来为交替元素设置样式。</p><p><code>li:nth-child(even) {     background-color: #f2f2f2; } li:nth-child(odd) {     background-color: #e6e6e6; } </code></p><h2 id="_25-css-计数器" tabindex="-1">25. CSS 计数器 <a class="header-anchor" href="#_25-css-计数器" aria-label="Permalink to &quot;25\\. CSS 计数器&quot;">​</a></h2><p>使用 counter-reset 和 counter-increment 属性在列表中创建自动编号。</p><p><code>ol {     counter-reset: item; } li {     counter-increment: item; } li::before {     content: counter(item) &quot;. &quot;; } </code></p><h2 id="_26-多重背景图片" tabindex="-1">26. 多重背景图片 <a class="header-anchor" href="#_26-多重背景图片" aria-label="Permalink to &quot;26\\. 多重背景图片&quot;">​</a></h2><p>使用不同属性为元素应用多个背景图片。</p><p><code>.bg {     background-image: url(&#39;image1.jpg&#39;), url(&#39;image2.jpg&#39;);     background-position: top left, bottom right;     background-repeat: no-repeat, repeat-x; } </code></p><h2 id="_27-优化文本流畅性的连字符" tabindex="-1">27. 优化文本流畅性的连字符 <a class="header-anchor" href="#_27-优化文本流畅性的连字符" aria-label="Permalink to &quot;27\\. 优化文本流畅性的连字符&quot;">​</a></h2><p>通过使用 hyphens 属性允许自动连字符以提高文本的可读性。</p><p><code>p {     hyphens: auto; } </code></p><h2 id="_28-使用-css-变量进行动态样式" tabindex="-1">28. 使用 CSS 变量进行动态样式 <a class="header-anchor" href="#_28-使用-css-变量进行动态样式" aria-label="Permalink to &quot;28\\. 使用 CSS 变量进行动态样式&quot;">​</a></h2><p>利用 CSS 变量创建动态且可重用的样式。</p><p><code>:root {     --main-color: #3498db; } .element {     color: var(--main-color); } </code></p><h2 id="_29-键盘导航的焦点样式" tabindex="-1">29. 键盘导航的焦点样式 <a class="header-anchor" href="#_29-键盘导航的焦点样式" aria-label="Permalink to &quot;29\\. 键盘导航的焦点样式&quot;">​</a></h2><p>改善焦点样式以提高键盘导航和可访问性。</p><p><code>:focus {     outline: 2px solid #27ae60; } </code></p><h2 id="_30-平滑渐变过渡" tabindex="-1">30. 平滑渐变过渡 <a class="header-anchor" href="#_30-平滑渐变过渡" aria-label="Permalink to &quot;30\\. 平滑渐变过渡&quot;">​</a></h2><p>为渐变背景应用平滑过渡效果，增强视觉效果。</p><p><code>.gradient-box {     background: linear-gradient(45deg, #3498db, #2ecc71);     transition: background 0.5s ease; } .gradient-box:hover {     background: linear-gradient(45deg, #e74c3c, #f39c12); } </code></p><h2 id="_31-文本描边效果" tabindex="-1">31. 文本描边效果 <a class="header-anchor" href="#_31-文本描边效果" aria-label="Permalink to &quot;31\\. 文本描边效果&quot;">​</a></h2><p>为文本添加描边，产生独特的视觉效果。</p><p><code>h1 {     color: #3498db;     -webkit-text-stroke: 2px #2c3e50; } </code></p><h2 id="_32-纯-css-汉堡菜单" tabindex="-1">32. 纯 CSS 汉堡菜单 <a class="header-anchor" href="#_32-纯-css-汉堡菜单" aria-label="Permalink to &quot;32\\. 纯 CSS 汉堡菜单&quot;">​</a></h2><p>创建一个简单的汉堡菜单，无需使用 JavaScript。</p><p><code>.menu-toggle {     display: none; } .menu-toggle:checked + nav {     display: block; } /* 在这里添加汉堡菜单图标和菜单样式 */ </code></p><h2 id="_33-css-is-选择器" tabindex="-1">33. CSS :is()选择器 <a class="header-anchor" href="#_33-css-is-选择器" aria-label="Permalink to &quot;33\\. CSS :is()选择器&quot;">​</a></h2><p>使用:is()伪类简化复杂的选择器。</p><p><code>:is(h1, h2, h3) {     color: blue; } </code></p><h2 id="_34-css-变量中的计算" tabindex="-1">34. CSS 变量中的计算 <a class="header-anchor" href="#_34-css-变量中的计算" aria-label="Permalink to &quot;34\\. CSS 变量中的计算&quot;">​</a></h2><p>在 CSS 变量中进行计算，实现动态样式。</p><p><code>:root {     --base-size: 16px;     --header-size: calc(var(--base-size) * 2); } h1 {     font-size: var(--header-size); } </code></p><h2 id="_35-attr-函数用于内容" tabindex="-1">35. attr()函数用于内容 <a class="header-anchor" href="#_35-attr-函数用于内容" aria-label="Permalink to &quot;35\\. attr()函数用于内容&quot;">​</a></h2><p>使用 attr</p><p>()函数检索和显示属性值。</p><p><code>div::before {     content: attr(data-custom-content); } </code></p><h2 id="_36-css-遮罩效果" tabindex="-1">36. CSS 遮罩效果 <a class="header-anchor" href="#_36-css-遮罩效果" aria-label="Permalink to &quot;36\\. CSS 遮罩效果&quot;">​</a></h2><p>为图像应用遮罩，创造出独特的效果。</p><p><code>.masked-image {     mask: url(mask.svg);     mask-size: cover; } </code></p><h2 id="_37-混合模式" tabindex="-1">37. 混合模式 <a class="header-anchor" href="#_37-混合模式" aria-label="Permalink to &quot;37\\. 混合模式&quot;">​</a></h2><p>尝试使用混合模式创建有趣的色彩效果。</p><p><code>.blend-mode {     background: url(image.jpg);     mix-blend-mode: screen; } </code></p><h2 id="_38-纵横比属性" tabindex="-1">38. 纵横比属性 <a class="header-anchor" href="#_38-纵横比属性" aria-label="Permalink to &quot;38\\. 纵横比属性&quot;">​</a></h2><p>使用纵横比属性简化纵横比盒子的创建。</p><p><code>.aspect-ratio-box {     aspect-ratio: 16/9; } </code></p><h2 id="_39-shape-outside-实现文本环绕" tabindex="-1">39. shape-outside 实现文本环绕 <a class="header-anchor" href="#_39-shape-outside-实现文本环绕" aria-label="Permalink to &quot;39\\. shape-outside 实现文本环绕&quot;">​</a></h2><p>使用 shape-outside 属性使文本围绕指定形状，实现更动态的布局。</p><p><code>.shape-wrap {     float: left;     width: 150px;     height: 150px;     shape-outside: circle(50%); } </code></p><h2 id="_40-ch-单位用于一致的尺寸" tabindex="-1">40. ch 单位用于一致的尺寸 <a class="header-anchor" href="#_40-ch-单位用于一致的尺寸" aria-label="Permalink to &quot;40\\. ch 单位用于一致的尺寸&quot;">​</a></h2><p>ch 单位表示所选字体中字符“0”的宽度，可用于创建一致且响应式的布局。</p><p><code>h1 {     font-size: 2ch; } </code></p><h2 id="_41-marker-伪元素" tabindex="-1">41. ::marker 伪元素 <a class="header-anchor" href="#_41-marker-伪元素" aria-label="Permalink to &quot;41\\. ::marker 伪元素&quot;">​</a></h2><p>使用::marker 伪元素为列表项标记设置样式。</p><p><code>li::marker {     color: blue; } </code></p><h2 id="_42-element-函数用于背景" tabindex="-1">42. element()函数用于背景 <a class="header-anchor" href="#_42-element-函数用于背景" aria-label="Permalink to &quot;42\\. element()函数用于背景&quot;">​</a></h2><p>使用 element()函数动态引用元素作为背景。</p><p><code>.background {     background: element(#targetElement); } </code></p><h2 id="_43-flexbox-实现粘性底部" tabindex="-1">43. Flexbox 实现粘性底部 <a class="header-anchor" href="#_43-flexbox-实现粘性底部" aria-label="Permalink to &quot;43\\. Flexbox 实现粘性底部&quot;">​</a></h2><p>使用 Flexbox 创建粘性底部布局。</p><p><code>body {     display: flex;     flex-direction: column;     min-height: 100vh; } main {     flex: 1; } </code></p><h2 id="_44-scroll-padding-实现平滑滚动" tabindex="-1">44. scroll-padding 实现平滑滚动 <a class="header-anchor" href="#_44-scroll-padding-实现平滑滚动" aria-label="Permalink to &quot;44\\. scroll-padding 实现平滑滚动&quot;">​</a></h2><p>通过调整 scroll padding 来改善滚动行为。</p><p><code>html {     scroll-padding: 20px; } </code></p><h2 id="_45-交互式高亮效果" tabindex="-1">45. 交互式高亮效果 <a class="header-anchor" href="#_45-交互式高亮效果" aria-label="Permalink to &quot;45\\. 交互式高亮效果&quot;">​</a></h2><p>使用 CSS 变量创建交互式高亮效果。</p><p><code>.highlight {     --highlight-color: #e74c3c;     background-image: linear-gradient(transparent 0%, var(--highlight-color) 0%);     background-size: 100% 200%;     transition: background-position 0.3s; } .highlight:hover {     background-position: 0 100%; } </code></p><h2 id="_46-自定义单选框和复选框样式" tabindex="-1">46. 自定义单选框和复选框样式 <a class="header-anchor" href="#_46-自定义单选框和复选框样式" aria-label="Permalink to &quot;46\\. 自定义单选框和复选框样式&quot;">​</a></h2><p>无需图像，样式化单选框和复选框。</p><p><code>input[type=&quot;radio&quot;] {     appearance: none;     -webkit-appearance: none;     border-radius: 50%;     width: 16px;     height: 16px;     border: 2px solid #3498db; } input[type=&quot;checkbox&quot;] {     appearance: none;     -webkit-appearance: none;     width: 16px;     height: 16px;     border: 2px solid #e74c3c; } </code></p><h2 id="_47-textarea-的-resize-属性" tabindex="-1">47. textarea 的 resize 属性 <a class="header-anchor" href="#_47-textarea-的-resize-属性" aria-label="Permalink to &quot;47\\. textarea 的 resize 属性&quot;">​</a></h2><p>使用 resize 属性控制 textarea 的调整大小行为。</p><p><code>textarea {     resize: vertical; } </code></p><h2 id="_48-文本渐变效果" tabindex="-1">48. 文本渐变效果 <a class="header-anchor" href="#_48-文本渐变效果" aria-label="Permalink to &quot;48\\. 文本渐变效果&quot;">​</a></h2><p>使用 background-clip 和 text-fill-color 属性为文本创建渐变效果。</p><p><code>.gradient-text {     background-image: linear-gradient(45deg, #3498db, #2ecc71);     background-clip: text;     color: transparent; } </code></p><h2 id="_49-对长单词使用-word-break-属性" tabindex="-1">49. 对长单词使用 word-break 属性 <a class="header-anchor" href="#_49-对长单词使用-word-break-属性" aria-label="Permalink to &quot;49\\. 对长单词使用 word-break 属性&quot;">​</a></h2><p>使用 word-break 属性控制长单词或没有空格的字符串的断行和换行。</p><p><code>.long-words {     word-break: break-all; } </code></p><h2 id="_50-font-variation-settings-用于可变字体" tabindex="-1">50. font-variation-settings 用于可变字体 <a class="header-anchor" href="#_50-font-variation-settings-用于可变字体" aria-label="Permalink to &quot;50\\. font-variation-settings 用于可变字体&quot;">​</a></h2><p>使用 font-variation-settings 属性微调可变字体样式。</p><p><code>.custom-font {     font-family: &#39;MyVariableFont&#39;;     font-variation-settings: &#39;wght&#39; 600, &#39;ital&#39; 1; } </code></p><h2 id="_51-混合模式用于创意叠加效果" tabindex="-1">51. 混合模式用于创意叠加效果 <a class="header-anchor" href="#_51-混合模式用于创意叠加效果" aria-label="Permalink to &quot;51\\. 混合模式用于创意叠加效果&quot;">​</a></h2><p>使用混合模式为元素应用叠加效果，创造出有趣的视觉效果。</p><p><code>.overlay {     mix-blend-mode: overlay; } </code></p><h2 id="_52-为损坏的图像应用样式" tabindex="-1">52. 为损坏的图像应用样式 <a class="header-anchor" href="#_52-为损坏的图像应用样式" aria-label="Permalink to &quot;52\\. 为损坏的图像应用样式&quot;">​</a></h2><p>使用:broken 伪类为损坏的图像应用样式。</p><p><code>img:broken {     filter: grayscale(100%); } </code></p><h2 id="_53-css-形状" tabindex="-1">53. CSS 形状 <a class="header-anchor" href="#_53-css-形状" aria-label="Permalink to &quot;53\\. CSS 形状&quot;">​</a></h2><p>使用 CSS 形状为设计创建有趣的效果。</p><p><code>.shape {     shape-outside: circle(50%); } </code></p><h2 id="_54-属性选择器用于子字符串匹配" tabindex="-1">54. 属性选择器用于子字符串匹配 <a class="header-anchor" href="#_54-属性选择器用于子字符串匹配" aria-label="Permalink to &quot;54\\. 属性选择器用于子字符串匹配&quot;">​</a></h2><p>使用*=操作符的属性选择器进行子字符串匹配。</p><p><code>[data-attribute*=&quot;value&quot;] {     /* 样式 */ } </code></p><h2 id="_55-backdrop-filter-用于模糊背景" tabindex="-1">55. backdrop-filter 用于模糊背景 <a class="header-anchor" href="#_55-backdrop-filter-用于模糊背景" aria-label="Permalink to &quot;55\\. backdrop-filter 用于模糊背景&quot;">​</a></h2><p>使用 backdrop-filter 为背景应用模糊效果，实现毛玻璃效果。</p><p><code>.element {     backdrop-filter: blur(10px); } </code></p><h2 id="_56-css-环境变量" tabindex="-1">56. CSS 环境变量 <a class="header-anchor" href="#_56-css-环境变量" aria-label="Permalink to &quot;56\\. CSS 环境变量&quot;">​</a></h2><p>使用 env()函数在 CSS 中访问环境变量。</p><p><code>.element {     margin-top: env(safe-area-inset-top); } </code></p><h2 id="_57-css-属性计数器" tabindex="-1">57. CSS 属性计数器 <a class="header-anchor" href="#_57-css-属性计数器" aria-label="Permalink to &quot;57\\. CSS 属性计数器&quot;">​</a></h2><p>使用:nth-child 选择器计算特定属性值的出现次数。</p><p><code>[data-category=&quot;example&quot;]:nth-child(3) {     /* 第三次出现的样式 */ } </code></p><h2 id="_58-css-形状实现文本环绕" tabindex="-1">58. CSS 形状实现文本环绕 <a class="header-anchor" href="#_58-css-形状实现文本环绕" aria-label="Permalink to &quot;58\\. CSS 形状实现文本环绕&quot;">​</a></h2><p>使用 shape-outside 结合 polygon()函数精确地控制文本围绕不规则形状的布局。</p><p><code>.text-wrap {     shape-outside: polygon(0 0, 100% 0, 100% 100%); } </code></p><h2 id="_59-自定义鼠标样式" tabindex="-1">59. 自定义鼠标样式 <a class="header-anchor" href="#_59-自定义鼠标样式" aria-label="Permalink to &quot;59\\. 自定义鼠标样式&quot;">​</a></h2><p>使用 cursor 属性更改鼠标样式。</p><p><code>.custom-cursor {     cursor: pointer; } </code></p><h2 id="_60-hsla-用于透明颜色" tabindex="-1">60. HSLA 用于透明颜色 <a class="header-anchor" href="#_60-hsla-用于透明颜色" aria-label="Permalink to &quot;60\\. HSLA 用于透明颜色&quot;">​</a></h2><p>使用 HSLA 值表示透</p><p>明颜色，对 alpha 通道进行更精细的控制。</p><p><code>.transparent-bg {     background-color: hsla(120, 100%, 50%, 0.5); } </code></p><h2 id="_61-text-orientation-实现纵向文本" tabindex="-1">61. text-orientation 实现纵向文本 <a class="header-anchor" href="#_61-text-orientation-实现纵向文本" aria-label="Permalink to &quot;61\\. text-orientation 实现纵向文本&quot;">​</a></h2><p>使用 text-orientation 属性将文本垂直旋转。</p><p><code>.vertical-text {     text-orientation: upright; } </code></p><h2 id="_62-font-variant-用于小型大写字母" tabindex="-1">62. font-variant 用于小型大写字母 <a class="header-anchor" href="#_62-font-variant-用于小型大写字母" aria-label="Permalink to &quot;62\\. font-variant 用于小型大写字母&quot;">​</a></h2><p>使用 font-variant 属性应用小型大写字母样式。</p><p><code>.small-caps {     font-variant: small-caps; } </code></p><h2 id="_63-box-decoration-break-用于背景分割" tabindex="-1">63. box-decoration-break 用于背景分割 <a class="header-anchor" href="#_63-box-decoration-break-用于背景分割" aria-label="Permalink to &quot;63\\. box-decoration-break 用于背景分割&quot;">​</a></h2><p>使用 box-decoration-break 属性控制跨多行断开的元素的背景，实现更灵活的文本环绕。</p><p><code>.split-background {     box-decoration-break: clone; } </code></p><h2 id="_64-focus-visible-用于特定焦点样式" tabindex="-1">64. :focus-visible 用于特定焦点样式 <a class="header-anchor" href="#_64-focus-visible-用于特定焦点样式" aria-label="Permalink to &quot;64\\. :focus-visible 用于特定焦点样式&quot;">​</a></h2><p>仅在元素处于焦点且焦点不是由鼠标单击提供时应用样式。</p><p><code>input:focus-visible {     outline: 2px solid blue; } </code></p><h2 id="_65-text-rendering-实现最佳字体呈现" tabindex="-1">65. text-rendering 实现最佳字体呈现 <a class="header-anchor" href="#_65-text-rendering-实现最佳字体呈现" aria-label="Permalink to &quot;65\\. text-rendering 实现最佳字体呈现&quot;">​</a></h2><p>通过 text-rendering 属性改善文本呈现效果。</p><p><code>.optimized-text {     text-rendering: optimizeLegibility; } </code></p><h2 id="_66-initial-letter-用于大写字母" tabindex="-1">66. initial-letter 用于大写字母 <a class="header-anchor" href="#_66-initial-letter-用于大写字母" aria-label="Permalink to &quot;66\\. initial-letter 用于大写字母&quot;">​</a></h2><p>使用 initial-letter 为块级元素的第一个字母应用样式。</p><p><code>p::first-letter {     font-size: 2em; } </code></p><h2 id="_67-overscroll-behavior-用于滚动过度" tabindex="-1">67. overscroll-behavior 用于滚动过度 <a class="header-anchor" href="#_67-overscroll-behavior-用于滚动过度" aria-label="Permalink to &quot;67\\. overscroll-behavior 用于滚动过度&quot;">​</a></h2><p>控制用户滚动超出滚动容器边界时的行为。</p><p><code>.scroll-container {     overscroll-behavior: contain; } </code></p><h2 id="_68-writing-mode-实现纵向布局" tabindex="-1">68. writing-mode 实现纵向布局 <a class="header-anchor" href="#_68-writing-mode-实现纵向布局" aria-label="Permalink to &quot;68\\. writing-mode 实现纵向布局&quot;">​</a></h2><p>使用 writing-mode 属性创建纵向布局。</p><p><code>.vertical-layout {     writing-mode: vertical-rl; } </code></p><h2 id="_69-cue-用于-html5-标题样式" tabindex="-1">69. ::cue 用于 HTML5 标题样式 <a class="header-anchor" href="#_69-cue-用于-html5-标题样式" aria-label="Permalink to &quot;69\\. ::cue 用于 HTML5 标题样式&quot;">​</a></h2><p>使用::cue 伪元素为 HTML5 字幕文本应用样式。</p><p><code>::cue {     color: blue; } </code></p><h2 id="_70-line-clamp-截断多行文本" tabindex="-1">70. line-clamp 截断多行文本 <a class="header-anchor" href="#_70-line-clamp-截断多行文本" aria-label="Permalink to &quot;70\\. line-clamp 截断多行文本&quot;">​</a></h2><p>使用 line-clamp 属性限制元素中显示的行数。</p><p><code>.truncated-text {     display: -webkit-box;     -webkit-line-clamp: 3;     -webkit-box-orient: vertical;     overflow: hidden; } </code></p><h2 id="_71-scroll-snap-align" tabindex="-1">71. scroll-snap-align <a class="header-anchor" href="#_71-scroll-snap-align" aria-label="Permalink to &quot;71\\. scroll-snap-align&quot;">​</a></h2><p>scroll-snap-align 属性控制滚动容器内滚动捕捉点的对齐方式，确保对滚动行为进行精确控制，提升用户体验。</p><p><code>.container {     scroll-snap-type: x mandatory; } .item {     scroll-snap-align: center; } </code></p><h2 id="_72-overscroll-behavior" tabindex="-1">72. overscroll-behavior <a class="header-anchor" href="#_72-overscroll-behavior" aria-label="Permalink to &quot;72\\. overscroll-behavior&quot;">​</a></h2><p>overscroll-behavior 使您可以定义浏览器在滚动超出范围时的处理方式，从而避免不必要的滚动效果，提升整体滚动体验。</p><p><code>.scrollable {     overscroll-behavior: contain; } </code></p><h2 id="_73-font-kerning" tabindex="-1">73. font-kerning <a class="header-anchor" href="#_73-font-kerning" aria-label="Permalink to &quot;73\\. font-kerning&quot;">​</a></h2><p>font-kerning 允许对字符间距进行微调，通过调整文本元素中字符之间的间距，确保最佳的可读性。</p><p><code>p {     font-kerning: auto; } </code></p><h2 id="_74-shape-margin" tabindex="-1">74. shape-margin <a class="header-anchor" href="#_74-shape-margin" aria-label="Permalink to &quot;74\\. shape-margin&quot;">​</a></h2><p>与 CSS 形状一起使用时，shape-margin 指定浮动元素形状周围的边距，可以更精确地控制文本环绕和布局。</p><p><code>.shape {     shape-margin: 20px; } </code></p><h2 id="_75-scroll-margin" tabindex="-1">75. scroll-margin <a class="header-anchor" href="#_75-scroll-margin" aria-label="Permalink to &quot;75\\. scroll-margin&quot;">​</a></h2><p>scroll-margin 设置滚动容器边缘与滚动内容开始之间的边距，提升用户体验，为滚动提供缓冲空间。</p><p><code>.container {     scroll-margin-top: 100px; } </code></p><h2 id="_76-tab-size" tabindex="-1">76. tab-size <a class="header-anchor" href="#_76-tab-size" aria-label="Permalink to &quot;76\\. tab-size&quot;">​</a></h2><p>tab-size 属性控制文本区域中制表符的宽度，确保在不同用户代理中一致的显示。</p><p><code>pre {     tab-size: 4; } </code></p><h2 id="_77-text-align-last" tabindex="-1">77. text-align-last <a class="header-anchor" href="#_77-text-align-last" aria-label="Permalink to &quot;77\\. text-align-last&quot;">​</a></h2><p>text-align-last 决定块级元素中最后一行文本的对齐方式，为多行块文本提供对齐控制。</p><p><code>p {     text-align-last: justify; } </code></p><h2 id="_78-text-justify" tabindex="-1">78. text-justify <a class="header-anchor" href="#_78-text-justify" aria-label="Permalink to &quot;78\\. text-justify&quot;">​</a></h2><p>此属性控制文本两端对齐的行为，指定是使用单词间还是字符间距进行文本对齐。</p><p><code>p {     text-align: justify;     text-justify: inter-word; } </code></p><h2 id="_79-column-fill" tabindex="-1">79. column-fill <a class="header-anchor" href="#_79-column-fill" aria-label="Permalink to &quot;79\\. column-fill&quot;">​</a></h2><p>column-fill 决定如何在多列布局中分配内容，允许内容依次或平衡分布在列中。</p><p><code>.container {     column-count: 3;     column-fill: auto; } </code></p><h2 id="_80-outline-offset" tabindex="-1">80. outline-offset <a class="header-anchor" href="#_80-outline-offset" aria-label="Permalink to &quot;80\\. outline-offset&quot;">​</a></h2><p>outline-offset 调整轮廓与元素边缘之间的空间，不影响布局，为轮廓的外观提供更细致的控制。</p><p><code>button {     outline: 2px solid blue;     outline-offset: 4px; } </code></p><h2 id="_81-font-variant-numeric" tabindex="-1">81. font-variant-numeric <a class="header-anchor" href="#_81-font-variant-numeric" aria-label="Permalink to &quot;81\\. font-variant-numeric&quot;">​</a></h2><p>此属性允许精细控制数字字体渲染，启用特性如数字大小写和分数、序数指示器等。</p><p><code>p {     font-variant-numeric: lining-nums; } </code></p><h2 id="_82-font-optical-sizing" tabindex="-1">82. font-optical-sizing <a class="header-anchor" href="#_82-font-optical-sizing" aria-label="Permalink to &quot;82\\. font-optical-sizing&quot;">​</a></h2><p>启用或禁用字体光学大小调整，以调整字符的间距和比例，实现在不同字体大小下更好的视觉和谐。</p><p><code>p {     font-optical-sizing: auto; } </code></p><h2 id="_83-text-decoration-thickness" tabindex="-1">83. text-decoration-thickness <a class="header-anchor" href="#_83-text-decoration-thickness" aria-label="Permalink to &quot;83\\. text-decoration-thickness&quot;">​</a></h2><p>精确控制文本装饰（如下划线、上划线和删除线）的粗细，实现精细化定制。</p><p><code>p {     text-decoration-thickness: 2px; } </code></p><h2 id="_84-text-decoration-skip-ink" tabindex="-1">84. text-decoration-skip-ink <a class="header-anchor" href="#_84-text-decoration-skip-ink" aria-label="Permalink to &quot;84\\. text-decoration-skip-ink&quot;">​</a></h2><p>text-decoration-skip-ink 属性控制文本装饰（如下划线）在被墨水遮挡的情况下是否继续绘制，提升可读性。</p><p><code>a {     text-decoration-skip-ink: auto; } </code></p><h2 id="_85-word-spacing" tabindex="-1">85. word-spacing <a class="header-anchor" href="#_85-word-spacing" aria-label="Permalink to &quot;85\\. word-spacing&quot;">​</a></h2><p>word-spacing 属性控制字词间距，调整文本的紧凑度和可读性。</p><p><code>p {     word-spacing: 2px; } </code></p><h2 id="_86-hyphenation" tabindex="-1">86. hyphenation <a class="header-anchor" href="#_86-hyphenation" aria-label="Permalink to &quot;86\\. hyphenation&quot;">​</a></h2><p>通过调整断字点和断字行为，提高文本在窄列中的美观度和可读性。</p><p><code>p {     hyphens: auto; } </code></p><h2 id="_87-background-blend-mode" tabindex="-1">87. background-blend-mode <a class="header-anchor" href="#_87-background-blend-mode" aria-label="Permalink to &quot;87\\. background-blend-mode&quot;">​</a></h2><p>background-blend-mode 属性允许背景图像与其下方的背景颜色进行混合，产生出独特的视觉效果。</p><p><code>.element {     background-image: url(&#39;image.jpg&#39;);     background-color: #3498db;     background-blend-mode: multiply; } </code></p><h2 id="_88-text-decoration-color" tabindex="-1">88. text-decoration-color <a class="header-anchor" href="#_88-text-decoration-color" aria-label="Permalink to &quot;88\\. text-decoration-color&quot;">​</a></h2><p>text-decoration-color 属性控制文本装饰的颜色，为链接和装饰文本提供更灵活的样式。</p><p><code>a {     text-decoration: underline;     text-decoration-color: red; } </code></p><h2 id="_89-overflow-anchor" tabindex="-1">89. overflow-anchor <a class="header-anchor" href="#_89-overflow-anchor" aria-label="Permalink to &quot;89\\. overflow-anchor&quot;">​</a></h2><p>overflow-anchor 属性指定了在容器的滚动范围内滚动时哪些内容应保持可见，提升用户体验。</p><p><code>.container {     overflow-anchor: none; } </code></p><h2 id="_90-contain-intrinsic-size" tabindex="-1">90. contain-intrinsic-size <a class="header-anchor" href="#_90-contain-intrinsic-size" aria-label="Permalink to &quot;90\\. contain-intrinsic-size&quot;">​</a></h2><p>contain-intrinsic-size 属性定义了内联大小计算函数的大小，实现更精确的布局控制。</p><p><code>img {     contain-intrinsic-size: 200px 300px; } </code></p><h2 id="_91-line-gap" tabindex="-1">91. line-gap <a class="header-anchor" href="#_91-line-gap" aria-label="Permalink to &quot;91\\. line-gap&quot;">​</a></h2><p>line-gap 属性定义了元素的行间距，可以为文字和其他行内元素提供更大的空间。</p><p><code>p {     line-gap: 1.5; } </code></p><h2 id="_92-text-underline-offset" tabindex="-1">92. text-underline-offset <a class="header-anchor" href="#_92-text-underline-offset" aria-label="Permalink to &quot;92\\. text-underline-offset&quot;">​</a></h2><p>text-underline-offset 属性控制文本下划线相对于基线的垂直偏移量，实现更加精确的下划线定位。</p><p><code>a {     text-decoration: underline;     text-underline-offset: 3px; } </code></p><h2 id="_93-text-decoration-line" tabindex="-1">93. text-decoration-line <a class="header-anchor" href="#_93-text-decoration-line" aria-label="Permalink to &quot;93\\. text-decoration-line&quot;">​</a></h2><p>text-decoration-line 属性指定要绘制的装饰线的类型，可用于单独控制上划线、下划线、删除线等。</p><p><code>a {     text-decoration-line: underline overline; } </code></p><h2 id="_94-text-emphasis" tabindex="-1">94. text-emphasis <a class="header-anchor" href="#_94-text-emphasis" aria-label="Permalink to &quot;94\\. text-emphasis&quot;">​</a></h2><p>text-emphasis 属性为文本设置强调标志，用于提高关键字的可读性。</p><p><code>em {     text-emphasis: filled circle; } </code></p><h2 id="_95-text-orientation" tabindex="-1">95. text-orientation <a class="header-anchor" href="#_95-text-orientation" aria-label="Permalink to &quot;95\\. text-orientation&quot;">​</a></h2><p>text-orientation 属性控制文本的方向，适用于纵向文本和日文排版等情况。</p><p><code>.vertical-text {     text-orientation: sideways-right; } </code></p><h2 id="_96-background-origin" tabindex="-1">96. background-origin <a class="header-anchor" href="#_96-background-origin" aria-label="Permalink to &quot;96\\. background-origin&quot;">​</a></h2><p>background-origin 属性确定背景图片的起始位置，影响背景图片与边框的相对位置。</p><p><code>.element {     background-image: url(&#39;image.jpg&#39;);     background-origin: content-box; } </code></p><h2 id="_97-counter-set" tabindex="-1">97. counter-set <a class="header-anchor" href="#_97-counter-set" aria-label="Permalink to &quot;97\\. counter-set&quot;">​</a></h2><p>counter-set 属性在使用 counter-reset 创建的计数器值基础上，显式设置一个新的值。</p><p><code>ol {     counter-set: section 1; } </code></p><h2 id="_98-hanging-punctuation" tabindex="-1">98. hanging-punctuation <a class="header-anchor" href="#_98-hanging-punctuation" aria-label="Permalink to &quot;98\\. hanging-punctuation&quot;">​</a></h2><p>hanging-punctuation 属性控制标点符号是否在行框之外悬挂，以提高排版的美观度和可读性。</p><p><code>p {     hanging-punctuation: last allow-end; } </code></p><h2 id="_99-line-break" tabindex="-1">99. line-break <a class="header-anchor" href="#_99-line-break" aria-label="Permalink to &quot;99\\. line-break&quot;">​</a></h2><p>line-break 属性控制文本换行行为，确保在指定的断点处进行断行。</p><p><code>p {     line-break: anywhere; } </code></p><h2 id="_100-text-justify" tabindex="-1">100. text-justify <a class="header-anchor" href="#_100-text-justify" aria-label="Permalink to &quot;100\\. text-justify&quot;">​</a></h2><p>text-justify 属性指定如何分配额外的空间，以便充分利用容器的宽度。</p><p><code>p {     text-align: justify;     text-justify: inter-word; } </code></p>',304))])}const k=n(p,[["render",s]]);export{g as __pageData,k as default};
